   1→//! V2 repository methods for canonical bronze data and control-plane tables.
   2→//!
   3→//! All methods are added as `impl Repository` so callers use the same
   4→//! `Repository` value they already hold for V1 wallet-scoped queries.
   5→
   6→use chrono::{DateTime, Utc};
   7→use spectraplex_core::v2::{
   8→    ChainFamily, Checkpoint, DatasetVersion, IndexTarget, IngestionRun, Network, RawTransaction,
   9→    TargetKind, TargetMatch, TargetMode,
  10→};
  11→use sqlx::Row;
  12→use uuid::Uuid;
  13→
  14→use crate::repo::Repository;
  15→
  16→// ---------------------------------------------------------------------------
  17→// Enum ↔ SQL string helpers
  18→// ---------------------------------------------------------------------------
  19→
  20→/// Convert a `ChainFamily` to the string used by `chain_family_enum` in SQL.
  21→pub fn chain_family_to_sql(cf: &ChainFamily) -> &'static str {
  22→    match cf {
  23→        ChainFamily::Solana => "solana",
  24→        ChainFamily::Evm => "evm",
  25→        ChainFamily::Hyperliquid => "hyperliquid",
  26→    }
  27→}
  28→
  29→/// Parse a SQL `chain_family_enum` string back to `ChainFamily`.
  30→pub fn sql_to_chain_family(s: &str) -> anyhow::Result<ChainFamily> {
  31→    match s {
  32→        "solana" => Ok(ChainFamily::Solana),
  33→        "evm" => Ok(ChainFamily::Evm),
  34→        "hyperliquid" => Ok(ChainFamily::Hyperliquid),
  35→        _ => Err(anyhow::anyhow!("Unknown chain_family: {s}")),
  36→    }
  37→}
  38→
  39→/// Convert a `TargetKind` to the string used by `target_kind_enum` in SQL.
  40→pub fn target_kind_to_sql(tk: &TargetKind) -> &'static str {
  41→    match tk {
  42→        TargetKind::Wallet => "wallet",
  43→        TargetKind::Contract => "contract",
  44→        TargetKind::Program => "program",
  45→        TargetKind::Account => "account",
  46→        TargetKind::TopicFilter => "topic_filter",
  47→        TargetKind::Market => "market",
  48→        TargetKind::Pool => "pool",
  49→        TargetKind::Protocol => "protocol",
  50→    }
  51→}
  52→
  53→/// Parse a SQL `target_kind_enum` string back to `TargetKind`.
  54→pub fn sql_to_target_kind(s: &str) -> anyhow::Result<TargetKind> {
  55→    match s {
  56→        "wallet" => Ok(TargetKind::Wallet),
  57→        "contract" => Ok(TargetKind::Contract),
  58→        "program" => Ok(TargetKind::Program),
  59→        "account" => Ok(TargetKind::Account),
  60→        "topic_filter" => Ok(TargetKind::TopicFilter),
  61→        "market" => Ok(TargetKind::Market),
  62→        "pool" => Ok(TargetKind::Pool),
  63→        "protocol" => Ok(TargetKind::Protocol),
  64→        _ => Err(anyhow::anyhow!("Unknown target_kind: {s}")),
  65→    }
  66→}
  67→
  68→/// Convert a `TargetMode` to the string used by `target_mode_enum` in SQL.
  69→pub fn target_mode_to_sql(tm: &TargetMode) -> &'static str {
  70→    match tm {
  71→        TargetMode::Backfill => "backfill",
  72→        TargetMode::Stream => "stream",
  73→        TargetMode::Both => "both",
  74→    }
  75→}
  76→
  77→/// Parse a SQL `target_mode_enum` string back to `TargetMode`.
  78→pub fn sql_to_target_mode(s: &str) -> anyhow::Result<TargetMode> {
  79→    match s {
  80→        "backfill" => Ok(TargetMode::Backfill),
  81→        "stream" => Ok(TargetMode::Stream),
  82→        "both" => Ok(TargetMode::Both),
  83→        _ => Err(anyhow::anyhow!("Unknown target_mode: {s}")),
  84→    }
  85→}
  86→
  87→// ---------------------------------------------------------------------------
  88→// Row-mapping helpers
  89→// ---------------------------------------------------------------------------
  90→
  91→fn row_to_network(row: &sqlx::postgres::PgRow) -> anyhow::Result<Network> {
  92→    let family_str: String = row.try_get("chain_family")?;
  93→    Ok(Network {
  94→        id: row.try_get("id")?,
  95→        chain_family: sql_to_chain_family(&family_str)?,
  96→        display_name: row.try_get("display_name")?,
  97→        is_testnet: row.try_get("is_testnet")?,
  98→        finality_model: {
  99→            let s: String = row.try_get("finality_model")?;
 100→            s.parse()
 101→                .map_err(|_| anyhow::anyhow!("bad finality_model: {s}"))?
 102→        },
 103→        block_time_ms: row.try_get("block_time_ms")?,
 104→    })
 105→}
