 188→// ---------------------------------------------------------------------------
 189→// Query builders (pub for unit-testing)
 190→// ---------------------------------------------------------------------------
 191→
 192→/// Build a batch INSERT for `raw_transactions` with ON CONFLICT DO NOTHING.
 193→pub fn build_raw_transaction_insert(
 194→    txs: &[RawTransaction],
 195→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
 196→    let mut query = String::from(
 197→        "INSERT INTO raw_transactions \
 198→         (id, network, tx_hash, timestamp, block_number, raw_metadata, source, ingestion_run_id, ingested_at) \
 199→         VALUES ",
 200→    );
 201→    let mut args = sqlx::postgres::PgArguments::default();
 202→    for (i, tx) in txs.iter().enumerate() {
 203→        let base = i * 9;
 204→        if i > 0 {
 205→            query.push_str(", ");
 206→        }
 207→        query.push_str(&format!(
 208→            "(${}, ${}, ${}, ${}, ${}, ${}, ${}, ${}, ${})",
 209→            base + 1,
 210→            base + 2,
 211→            base + 3,
 212→            base + 4,
 213→            base + 5,
 214→            base + 6,
 215→            base + 7,
 216→            base + 8,
 217→            base + 9,
 218→        ));
 219→        use sqlx::Arguments;
 220→        args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
 221→        args.add(&tx.network).map_err(|e| anyhow::anyhow!("{e}"))?;
 222→        args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
 223→        args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
 224→        args.add(tx.block_number)
 225→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 226→        args.add(&tx.raw_metadata)
 227→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 228→        args.add(&tx.source).map_err(|e| anyhow::anyhow!("{e}"))?;
 229→        args.add(tx.ingestion_run_id)
 230→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 231→        args.add(tx.ingested_at)
 232→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 233→    }
 234→    query.push_str(" ON CONFLICT (network, tx_hash) DO NOTHING");
 235→    Ok((query, args))
 236→}
 237→
 238→/// Build a batch INSERT for `target_matches` with ON CONFLICT DO NOTHING.
 239→pub fn build_target_match_insert(
 240→    matches: &[TargetMatch],
 241→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
 242→    let mut query = String::from(
 243→        "INSERT INTO target_matches \
 244→         (id, target_id, raw_transaction_id, match_reason, matched_at) \
 245→         VALUES ",
 246→    );
 247→    let mut args = sqlx::postgres::PgArguments::default();
 248→    for (i, m) in matches.iter().enumerate() {
 249→        let base = i * 5;
 250→        if i > 0 {
 251→            query.push_str(", ");
 252→        }
 253→        query.push_str(&format!(
 254→            "(${}, ${}, ${}, ${}, ${})",
 255→            base + 1,
 256→            base + 2,
 257→            base + 3,
 258→            base + 4,
 259→            base + 5,
 260→        ));
 261→        use sqlx::Arguments;
 262→        args.add(m.id).map_err(|e| anyhow::anyhow!("{e}"))?;
 263→        args.add(m.target_id).map_err(|e| anyhow::anyhow!("{e}"))?;
 264→        args.add(m.raw_transaction_id)
 265→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 266→        args.add(&m.match_reason)
 267→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 268→        args.add(m.matched_at).map_err(|e| anyhow::anyhow!("{e}"))?;
 269→    }
 270→    query.push_str(" ON CONFLICT (target_id, raw_transaction_id) DO NOTHING");
 271→    Ok((query, args))
 272→}
